    {"text": "При t > 0 дебит скважины постоянен и равен Q0.", "claims": ["c4"]}
  ],
  "terms_defined": [
    {"term": "плоскорадиальный поток", "term_en": "plane-radial flow", "abbr": "", "definition": "Течение в горизонтальном пласте, где давление и скорость зависят от расстояния до скважины. Линии тока идут к скважине или от неё по радиусам.", "claims": ["c5", "c6"]},
    {"term": "точечный сток", "term_en": "point sink", "abbr": "", "definition": "Идеализация скважины как точки нулевого радиуса, из которой жидкость отбирается. Используется для упрощения расчётов.", "claims": ["c1"]},
    {"term": "неограниченный пласт", "term_en": "unbounded reservoir", "abbr": "", "definition": "Пласт без внешней границы. В расчётах его размер считают бесконечным.", "claims": ["c2"]}
  ],
